function useBuildVariant() {
  // The Vite dev server is always a preview build. In production the daemon
  // serves a build-variant.txt stamped by scripts/build-app.sh, so a Web UI
  // shipped by a release install stays unmarked.
  const [isBuild, setIsBuild] = useState(() => import.meta.env.DEV);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const response = await fetch(webAssetURL("build-variant.txt"), { cache: "no-store" });
        if (!response.ok) return;
        const value = (await response.text()).trim();
        if (!cancelled) setIsBuild(value === "build");
      } catch {
        // Keep the dev-server default; a release install without a marker
        // stays unmarked.
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  return isBuild;
}

// Roving focus for a composite list (the sidebar tree). Only the current item
// keeps `tabIndex = 0`, so Tab leaves the group in one stop while the arrows
// walk it. The item set is read from the DOM at event time, which means a
// collapsed project or a closed session can never leave a stale element pinned
// as the tab stop.
function useRovingFocus(containerRef, selector, { orientation = "vertical" } = {}) {
  const activeRef = useRef(0);

  const items = useCallback(() => {
    const root = containerRef.current;
    if (!root) return [];
    return [...root.querySelectorAll(selector)].filter(node => !node.disabled);
  }, [containerRef, selector]);

  const syncTabStops = useCallback(() => {
    const list = items();
    const active = rovingTabIndex(activeRef.current, list.length);
    activeRef.current = active;
    list.forEach((node, index) => {
      node.tabIndex = index === active ? 0 : -1;
    });
  }, [items]);

  // Re-apply after every render so a list that grew or shrank keeps exactly one
  // tab stop without threading an index through the tree renderer.
  useEffect(() => {
    syncTabStops();
  });

  const onFocus = useCallback(event => {
    const list = items();
    const index = list.indexOf(event.target);
    if (index < 0) return;
    activeRef.current = index;
    syncTabStops();
  }, [items, syncTabStops]);

  const onKeyDown = useCallback(event => {
    const list = items();
    const index = list.indexOf(event.target);
    if (index < 0) return;
    const next = rovingIndex(event.key, index, list.length, { orientation });
    if (next < 0) return;
    event.preventDefault();
    activeRef.current = next;
    syncTabStops();
    list[next]?.focus();
  }, [items, orientation, syncTabStops]);

  return { onFocus, onKeyDown };
}

// True while a scroll container has content past its viewport. Drives the
// sidebar's edge fade; re-checked whenever the caller's content dependencies
// change or the container resizes.
function useOverflowFlag(containerRef, deps) {
  const [overflowing, setOverflowing] = useState(false);

  useEffect(() => {
    const node = containerRef.current;
    if (!node || typeof ResizeObserver === "undefined") return undefined;
    const update = () => setOverflowing(node.scrollHeight - node.clientHeight > 1);
    update();
    const observer = new ResizeObserver(update);
    observer.observe(node);
    return () => observer.disconnect();
    // The caller owns the extra dependencies; they are spread so React sees a
    // stable list length as long as the call site stays fixed.
  }, [containerRef, ...deps]);

  return overflowing;
}

// App-owned overlays move focus into their first meaningful control. Keep the
// invoking control as the focus owner when the overlay goes away so Escape,
// Cancel, and a completed action never strand keyboard users at document.body.
function useFocusRestore(active) {
  const previousFocusRef = useRef(null);

  useEffect(() => {
    if (!active) return undefined;
    const current = document.activeElement;
    previousFocusRef.current = typeof HTMLElement !== "undefined"
      && current instanceof HTMLElement
      && current !== document.body
      ? current
      : null;
    return () => {
      const target = previousFocusRef.current;
      previousFocusRef.current = null;
      if (!target?.isConnected) return;
      queueMicrotask(() => {
        if (!target.isConnected) return;
        // A menu action can mount the next app-owned surface in the same
        // render. Let that surface own focus instead of racing it from the
        // closing overlay's cleanup task.
        const nextSurface = document.querySelector('[role="dialog"][aria-modal="true"], [role="menu"]');
        if (nextSurface && !nextSurface.contains(target)) return;
        const active = document.activeElement;
        if (active && active !== document.body && active !== target) return;
        target.focus({ preventScroll: true });
      });
    };
  }, [active]);
}

// Keep keyboard focus inside an app-owned dialog, sheet, or menu while it is
// open. Native browser focus can otherwise move behind the scrim after the
// initial focus lands, which is especially disorienting on compact screens.
// The drawn tooltip is hidden from assistive technology, so a tooltip that
// adds to a control's name, rather than being it, is also the control's
// description. Spread `props` onto the control and render `note` beside it;
// a `hidden` element still supplies an aria-describedby description.
export function tooltipDescription(id, text) {
  if (!text) return { props: {}, note: null };
  return {
    props: { "data-tooltip": text, "aria-describedby": id },
    note: <span id={id} hidden>{text}</span>,
  };
}

export function useTooltipDescription(text) {
  return tooltipDescription(useId(), text);
}

export function useFocusTrap(active, containerRef) {
  useEffect(() => {
    if (!active) return undefined;
    const container = containerRef.current;
    if (!container) return undefined;
    const selector = [
      'a[href]',
      'area[href]',
      'button:not([disabled])',
      'input:not([disabled])',
      'select:not([disabled])',
      'textarea:not([disabled])',
      '[tabindex]:not([tabindex="-1"])',
    ].join(",");
    const focusable = () => Array.from(container.querySelectorAll(selector))
      .filter(element => !element.hasAttribute("aria-hidden"));
    const handleKeyDown = event => {
      if (event.key !== "Tab") return;
      const items = focusable();
      if (!items.length) return;
      const first = items[0];
      const last = items[items.length - 1];
      const current = document.activeElement;
      if (!container.contains(current)) {
        event.preventDefault();
        (event.shiftKey ? last : first).focus();
      } else if (event.shiftKey && current === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && current === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener("keydown", handleKeyDown, true);
    return () => document.removeEventListener("keydown", handleKeyDown, true);
  }, [active, containerRef]);
}

// Fixed app-owned surfaces must own scrolling while they are visible. A shared
// counter keeps nested overlays from restoring the body's previous style while
// another surface still owns the lock.
let bodyScrollLockCount = 0;
let bodyScrollLockPreviousOverflow = null;

function useBodyScrollLock(active) {
  useEffect(() => {
    if (!active) return undefined;
    if (bodyScrollLockCount === 0) {
      bodyScrollLockPreviousOverflow = document.body.style.overflow;
    }
    bodyScrollLockCount += 1;
    document.body.style.overflow = "hidden";
    return () => {
      bodyScrollLockCount = Math.max(0, bodyScrollLockCount - 1);
      if (bodyScrollLockCount === 0) {
        document.body.style.overflow = bodyScrollLockPreviousOverflow || "";
        bodyScrollLockPreviousOverflow = null;
      }
    };
  }, [active]);
}

/// What this person has already seen, per Session, on this device
/// (`{ [sessionID]: lifecycle }`). Every dot reads it, so a completion read in
/// one place stops drawing everywhere at once.
export const ActivityAcknowledgmentsContext = createContext({});

function sessionMark(session, acknowledgments) {
  return resolveDrawnActivityMark(session?.agentStatus, acknowledgments[session?.id] ?? null);
}

/// One Agent status as a dot.
///
/// The hue carries what a state asks of a person and motion carries whether work
/// is progressing. Shape was tried for the states that want someone — a glyph
/// badge — and it read worse at the size a row actually uses, so the kind of a
/// request lives in the tooltip and the label instead.
///
/// Pass `session` for one Session's own dot, or a precomputed `mark` for a
/// rollup that already applied the acknowledgments.
export function ActivityDot({ session, mark: resolvedMark }) {
  const acknowledgments = useContext(ActivityAcknowledgmentsContext);
  const mark = resolvedMark === undefined ? sessionMark(session, acknowledgments) : resolvedMark;
  if (!mark) return null;
  const label = activityMarkLabel(mark);
  // The lifecycle class keeps carrying the hue, so the palette stays in one
  // place.
  const className = [
    "activity",
    activityMarkLifecycle(mark),
    activityMarkIsAnimated(mark) ? "pulse" : "",
  ].filter(Boolean).join(" ");
  return <span className={className} data-tooltip={label} aria-label={label} role="img" />;
}

function mergedBadgeTitle(tabs, acknowledgments) {
  const count = tabs.length;
  const parts = ["Merged to default branch"];
  if (count) parts.push(`${count} active`);
  const activity = activityMarkWord(highestMark(tabs, acknowledgments));
  if (activity) parts.push(activity);
  return parts.join(" · ");
}

export function MergedBadge({ tabs = [] }) {
  const acknowledgments = useContext(ActivityAcknowledgmentsContext);
  const label = mergedBadgeTitle(tabs, acknowledgments);
  return (
    <span className="merge-badge" data-tooltip={label} aria-label={label} role="img">
      {mergeIcon}
    </span>
  );
}

/**
 * The tile each Session kind wears, matching the Desktop's app icons: the
 * brand's mark in white on a tile of the brand's colour. Marks drawn in more
 * than one colour keep their artwork on a near-black tile instead.
 */
const SESSION_TILES = {
  claude: { asset: "preset-claude.svg", tile: "#D97757", white: true },
  // The white variant, so its inner counter-shape stays a hole under the mask.
  codex: { asset: "preset-codex-white.svg", tile: "#5B6CF0", white: true },
  opencode: { asset: "preset-opencode.svg", tile: "#26221F", white: true },
  pi: { asset: "preset-pi.svg", tile: "#26221F", white: true },
  qoder: { asset: "preset-qoder.svg", tile: "#26221F", white: false },
  antigravity: { asset: "preset-antigravity.svg", tile: "#26221F", white: false },
  trae: { asset: "preset-trae.svg", tile: "#26221F", white: false },
  browser: { asset: "preset-browser.svg", tile: "#3B78C4", white: true },
  // A Shell is drawn as the zsh it runs in, as on the Desktop.
  shell: { asset: "program-zsh.svg", tile: "#F15A24", white: true },
};

function SessionPresetIcon({ kind }) {
  const spec = SESSION_TILES[kind] || SESSION_TILES.shell;
  const url = webAssetURL(spec.asset);
  return (
    <span className={`preset-brand-icon preset-brand-icon-${kind}`} style={{ background: spec.tile }} aria-hidden="true">
      {spec.white
        ? <span className="preset-brand-glyph" style={{ maskImage: `url("${url}")`, WebkitMaskImage: `url("${url}")` }} />
        : <img src={url} alt="" />}
    </span>
  );
}

const foldStorageKeys = {
  idleWorktrees: "warren.sidebar.idleWorktrees",
  inactiveProjects: "warren.sidebar.inactiveProjects",
};

/// The folds this browser last left open, so a reload lands on the same tree.
function readRevealedFold(key) {
  try {
    const stored = JSON.parse(localStorage.getItem(key) || "[]");
    return new Set(Array.isArray(stored) ? stored.filter(value => typeof value === "string") : []);
  } catch {
    return new Set();
  }
}

function writeRevealedFold(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify([...value]));
  } catch {
    // Private browsing may refuse storage; the fold then starts closed.
  }
}

/// A Session under its Workspace, on the Desktop's grid: the app tile in the
/// 18px icon column with its status dot on the corner, then the title and,
/// when there is something to say, a second line. State only changes colour;
/// a row keeps its height.
function SidebarSessionRow({ session, workspace, active, acknowledgedLifecycle, onOpen, onContextMenu }) {
  const summary = sessionRowSummary(session);
  const mark = resolveDrawnActivityMark(session.agentStatus, acknowledgedLifecycle);
  // Working, waiting, failed, or done and not yet seen: the title steps up a
  // tier so the rows that want something stand out of a long list.
  const live = Boolean(mark && mark !== "exited");
  const lineTone = { attention: "ask", danger: "fail", live: "work" }[summary.tone] || (live ? "lively" : "rest");
  return (
    <button
      type="button"
      className={`session-row${active ? " active" : ""}${live ? " live" : ""}${summary.text ? " two" : ""}`}
      aria-current={active ? "page" : undefined}
      onClick={onOpen}
      onContextMenu={onContextMenu}
    >
      <span className="tree-icon session-row-icon">
        <SessionPresetIcon kind={sessionProvider(session)} />
        <ActivityDot session={session} />
      </span>
      <span className="session-row-text">
        <span className="session-row-title">{terminalTabTitle(session, workspace)}</span>
        {summary.text && <span className={`session-row-summary ${lineTone}`}>{summary.text}</span>}
      </span>
    </button>
  );
}

/// A branch in Avenir Next Condensed with its `feat/…/` prefix a step quieter.
function BranchName({ branch }) {
  const { prefix, name } = branchParts(branch);
  return (
    <span className="branch lane-branch">
      {prefix && <span className="branch-prefix">{prefix}</span>}
      {name}
    </span>
  );
}

/// What a folded Project keeps of what it hides: a dot per Session with a
/// state, then how many Sessions there are.
function FoldSummary({ sessions, acknowledgments }) {
  const marks = sessions
    .map(session => resolveDrawnActivityMark(session.agentStatus, acknowledgments[session.id] ?? null))
    .filter(mark => mark && mark !== "exited")
    .slice(0, 6);
  if (!sessions.length) return null;
  return (
    <span className="fold-summary" aria-label={`${sessions.length} session${sessions.length === 1 ? "" : "s"}`}>
      {marks.map((mark, index) => <ActivityDot key={index} mark={mark} />)}
      <span className="fold-count">{sessions.length}</span>
    </span>
  );
}

// Memoized: App re-renders on every terminal and Agent update, and the
// navigation only changes with the roster, the selection, or a drag.
export const Sidebar = memo(SidebarView);

function SidebarView({
  catalog,
  activeWorkspace,
  activeSession = null,
  hostName = "",
  expandedProjects,
  tabsForWorkspace,
  connection,
  onOpenSession,
  onSessionContextMenu,
  onToggleProject,
  onChooseWorkspace,
  onOpenWorkspace,
  onNewSessionInWorkspace,
  onNewSession,
  onOpenSearch,
  onOpenSettings,
  onProjectContextMenu,
  onWorkspaceContextMenu,
  onMoveProject,
  onMoveWorkspace,
  onBeginProjectDrag,
  onEndProjectDrag,
  creatingWorkspaceIDs = new Set(),
  creatingSession = false,
}) {
  const isBuild = useBuildVariant();
  const acknowledgments = useContext(ActivityAcknowledgmentsContext);
  const scrollRef = useRef(null);
  const scrollOverflows = useOverflowFlag(scrollRef, [catalog, expandedProjects]);
  const roving = useRovingFocus(scrollRef, ".sidebar-scroll button:not(:disabled)");
  const [dragState, setDragState] = useState(null);
  const [dragOverID, setDragOverID] = useState(null);
  const [dragOverPosition, setDragOverPosition] = useState(null);
  // Which folds the person opened. These are view preferences of this browser,
  // so they live here and persist locally instead of round-tripping through
  // App state.
  const [revealedIdle, setRevealedIdle] = useState(() => readRevealedFold(foldStorageKeys.idleWorktrees));
  const [revealedInactive, setRevealedInactive] = useState(() => readRevealedFold(foldStorageKeys.inactiveProjects));

  const toggleIdle = projectID => setRevealedIdle(previous => {
    const next = new Set(previous);
    if (next.has(projectID)) next.delete(projectID);
    else next.add(projectID);
    return next;
  });

  // A Project is active while one of its Workspaces holds a Session, or while
  // it is the one on screen; the rest fold behind one row, as on the Desktop.
  const bands = useMemo(() => projectBands(catalog.projects, {
    isActive: project => {
      const workspaces = catalog.workspacesByProject.get(project.id) || [];
      return workspaces.some(workspace => workspace.id === activeWorkspace)
        || workspaces.some(workspace => tabsForWorkspace(workspace.id).length > 0);
    },
    lastActiveAt: project => projectLastActiveAt(catalog.workspacesByProject.get(project.id) || []),
  }), [activeWorkspace, catalog, tabsForWorkspace]);
  const inactiveOpen = revealedInactive.has("all") || Boolean(dragState);
  const listed = inactiveOpen ? [...bands.pinned, ...bands.active, ...bands.inactive] : [...bands.pinned, ...bands.active];

  useEffect(() => {
    writeRevealedFold(foldStorageKeys.idleWorktrees, revealedIdle);
  }, [revealedIdle]);

  useEffect(() => {
    writeRevealedFold(foldStorageKeys.inactiveProjects, revealedInactive);
  }, [revealedInactive]);

  const beginDrag = (kind, id, projectID, event) => {
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("text/plain", id);
    setDragOverID(null);
    setDragOverPosition(null);
    setDragState({ kind, id, projectID });
    if (kind === "project") onBeginProjectDrag(expandedProjects);
  };

  const endDrag = () => {
    if (dragState?.kind === "project") onEndProjectDrag();
    setDragState(null);
    setDragOverID(null);
    setDragOverPosition(null);
  };

  const projectDragOver = (projectID, event) => {
    if (dragState?.kind !== "project") return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    const rect = event.currentTarget.getBoundingClientRect();
    const position = event.clientY < rect.top + rect.height / 2 ? "before" : "after";
    if (dragOverID !== projectID || dragOverPosition !== position) {
      setDragOverID(projectID);
      setDragOverPosition(position);
    }
  };

  const workspaceDragOver = (workspace, event) => {
    if (dragState?.kind !== "workspace" || dragState.projectID !== workspace.project) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    if (dragOverID !== workspace.id) setDragOverID(workspace.id);
  };

  const dropProject = (projectID, event) => {
    if (dragState?.kind !== "project") return;
    event.preventDefault();
    const rect = event.currentTarget.getBoundingClientRect();
    const beforeProjectID = event.clientY < rect.top + rect.height / 2
      ? projectID
      : projectAfter(projectID);
    onMoveProject(dragState.id, beforeProjectID);
    endDrag();
  };

  const projectIDs = catalog.projects.map(project => project.id);

  const projectAfter = projectID => {
    const index = projectIDs.indexOf(projectID);
    if (index < 0 || index + 1 >= projectIDs.length) return null;
    return projectIDs[index + 1];
  };

  const dropWorkspace = (workspace, event) => {
    if (dragState?.kind !== "workspace" || dragState.projectID !== workspace.project) return;
    event.preventDefault();
    onMoveWorkspace(dragState.id, workspace.id);
    endDrag();
  };

  return (
    <aside className="sidebar" aria-label="Projects and workspaces">
      <div className={connectionClassName("host-identity", connection)}>
        <span className="host-tile" aria-hidden="true">
          {monogram(hostName || "Warren").toLowerCase()}
          <span className="connection-dot" />
        </span>
        <span className="host-text">
          <span className="host-name">{hostName || "Warren"}</span>
          <span className="host-status">{connection.message}</span>
        </span>
        {isBuild && <span className="build-badge">Build</span>}
        {onOpenSearch && (
          <button type="button" className="tree-icon-button" aria-label="Search projects" data-tooltip="Search" onClick={onOpenSearch}>
            <SearchIcon />
          </button>
        )}
      </div>
      <div className="sidebar-tabs">
        <h2 className="sidebar-tab">
          Projects
          {catalog.projects.length > 0 && <span className="sidebar-tab-count">{catalog.projects.length}</span>}
        </h2>
        <button
          type="button"
          className="tree-icon-button"
          disabled={!activeWorkspace || creatingSession}
          aria-busy={creatingSession || undefined}
          aria-label="New session"
          data-tooltip="New session"
          onClick={onNewSession}
        >
          <PlusIcon />
        </button>
      </div>
      <div
        className="sidebar-scroll"
        ref={scrollRef}
        data-overflow={scrollOverflows ? "true" : undefined}
        onFocus={roving.onFocus}
        onKeyDown={roving.onKeyDown}
      >
        {listed.length ? listed.map((project, projectIndex) => {
          const workspaces = catalog.workspacesByProject.get(project.id) || [];
          const open = expandedProjects.has(project.id);
          const previousOpen = projectIndex > 0 && expandedProjects.has(listed[projectIndex - 1].id);
          const projectSessions = open ? [] : workspaces.flatMap(workspace => tabsForWorkspace(workspace.id));
          return (
            <section
              className={`project${open ? " open" : ""}${!open && projectIndex > 0 && !previousOpen ? " packed" : ""}`}
              key={project.id}
            >
              <div
                className={`project-toggle${dragOverID === project.id ? " drag-over" : ""}${dragOverID === project.id && dragOverPosition === "before" ? " drag-before" : ""}${dragOverID === project.id && dragOverPosition === "after" ? " drag-after" : ""}`}
                onContextMenu={event => onProjectContextMenu(event, project)}
                draggable
                onDragStart={event => beginDrag("project", project.id, null, event)}
                onDragEnd={endDrag}
                onDragOver={event => projectDragOver(project.id, event)}
                onDrop={event => dropProject(project.id, event)}
              >
                <button
                  type="button"
                  className="project-toggle-main"
                  aria-expanded={open}
                  onClick={() => onToggleProject(project.id)}
                >
                  <span className="tree-icon">
                    <span className="project-tile" style={{ "--tint": identityTint(project.id) }} aria-hidden="true">{monogram(project.name)}</span>
                  </span>
                  <span className="group-name">{project.name}</span>
                  {project.pinned && <span className="pin-icon" role="img" aria-label="Pinned" data-tooltip="Pinned">{pinIcon}</span>}
                </button>
                {workspaces[0] && (
                  <button
                    type="button"
                    className="project-add"
                    disabled={creatingSession || creatingWorkspaceIDs.has(workspaces[0].id)}
                    aria-busy={creatingWorkspaceIDs.has(workspaces[0].id) || undefined}
                    aria-label={`New session in ${project.name}`}
                    data-tooltip="New session"
                    onClick={event => {
                      event.stopPropagation();
                      (onNewSessionInWorkspace || onOpenWorkspace)(workspaces[0].id);
                    }}
                  >
                    <PlusIcon />
                  </button>
                )}
                {!open && <FoldSummary sessions={projectSessions} acknowledgments={acknowledgments} />}
                <button
                  type="button"
                  className="project-chevron"
                  aria-label={open ? `Collapse ${project.name}` : `Expand ${project.name}`}
                  onClick={() => onToggleProject(project.id)}
                >
                  <span className="chevron">{ChevronDownSmallIcon}</span>
                </button>
              </div>
              <div className="workspace-list">
                {(() => {
                  const { shown, idle } = partitionWorkspaces(
                    workspaces,
                    workspaceID => tabsForWorkspace(workspaceID).length,
                    activeWorkspace,
                  );
                  const idleOpen = revealedIdle.has(project.id) || Boolean(dragState);
                  const visible = idleOpen ? workspaces : shown;
                  return (
                    <>
                {visible.map(workspace => {
                  const creating = creatingWorkspaceIDs.has(workspace.id);
                  const sessions = tabsForWorkspace(workspace.id);
                  return (
                    <div className={`lane${sessions.length ? " has-sessions" : ""}`} key={workspace.id}>
                    <div
                      className={`workspace-row${workspace.id === activeWorkspace ? " active" : ""}${sessions.length ? " has-sessions" : ""}${creating ? " pending" : ""}${dragOverID === workspace.id ? " drag-over" : ""}`}
                      aria-busy={creating || undefined}
                      onContextMenu={event => onWorkspaceContextMenu(event, workspace)}
                      draggable
                      onDragStart={event => beginDrag("workspace", workspace.id, workspace.project, event)}
                      onDragEnd={endDrag}
                      onDragOver={event => workspaceDragOver(workspace, event)}
                      onDrop={event => dropWorkspace(workspace, event)}
                    >
                      <button
                        type="button"
                        className="workspace-row-main"
                        disabled={creating}
                        aria-busy={creating || undefined}
                        onClick={() => onChooseWorkspace(workspace.id)}
                        onDoubleClick={() => onOpenWorkspace(workspace.id)}
                      >
                        <span className="tree-icon">
                          {workspace.mergeState === "merged"
                            ? <MergedBadge tabs={sessions} />
                            : <BranchIcon />}
                        </span>
                        <BranchName branch={workspace.branch || workspace.name || "Workspace"} />
                        {workspace.pinned && <span className="pin-icon" role="img" aria-label="Pinned" data-tooltip="Pinned">{pinIcon}</span>}
                      </button>
                      {creating && <span className="workspace-pending" role="status">Creating…</span>}
                    </div>
                    {sessions.map(session => (
                      <SidebarSessionRow
                        key={session.id}
                        session={session}
                        workspace={workspace}
                        active={session.id === activeSession && workspace.id === activeWorkspace}
                        acknowledgedLifecycle={acknowledgments[session.id] ?? null}
                        onOpen={() => onOpenSession?.(workspace.id, session.id)}
                        onContextMenu={event => onSessionContextMenu?.(event, session)}
                      />
                    ))}
                    </div>
                  );
                })}
                {idle.length > 0 && !dragState && (
                  <button
                    type="button"
                    className="idle-worktrees"
                    aria-expanded={idleOpen}
                    onClick={() => toggleIdle(project.id)}
                  >
                    <span className="tree-icon"><BranchIcon /></span>
                    {idleOpen
                      ? <span className="idle-label">Hide idle worktrees</span>
                      : <span className="idle-label"><b>{idle.length}</b> idle worktree{idle.length === 1 ? "" : "s"}</span>}
                    <span className={`idle-chevron${idleOpen ? " open" : ""}`}>{ChevronDownSmallIcon}</span>
                  </button>
                )}
                    </>
                  );
                })()}
                {dragState?.kind === "workspace" && dragState.projectID === project.id && (
                  <div
                    className={`sidebar-drop-end${dragOverID === "__workspace_end" ? " drag-over" : ""}`}
                    onDragOver={event => {
                      event.preventDefault();
                      event.dataTransfer.dropEffect = "move";
                      if (dragOverID !== "__workspace_end") setDragOverID("__workspace_end");
                    }}
                    onDrop={event => {
                      if (dragState?.kind !== "workspace") return;
                      event.preventDefault();
                      onMoveWorkspace(dragState.id, null);
                      endDrag();
                    }}
                  />
                )}
              </div>
            </section>
          );
        }) : <div className="sidebar-empty">No projects</div>}
        {bands.inactive.length > 0 && (
          <button
            type="button"
            className="idle-worktrees inactive-projects"
            aria-expanded={inactiveOpen}
            onClick={() => setRevealedInactive(inactiveOpen ? new Set() : new Set(["all"]))}
          >
            <span className="tree-icon">
              <span className="project-stack" aria-hidden="true">
                {bands.inactive.slice(0, 3).map(project => (
                  <span className="project-tile" style={{ "--tint": identityTint(project.id) }} key={project.id}>
                    {monogram(project.name)}
                  </span>
                ))}
              </span>
            </span>
            {inactiveOpen
              ? <span className="idle-label">Hide inactive projects</span>
              : <span className="idle-label"><b>{bands.inactive.length}</b> inactive project{bands.inactive.length === 1 ? "" : "s"}</span>}
            <span className={`idle-chevron${inactiveOpen ? " open" : ""}`}>{ChevronDownSmallIcon}</span>
          </button>
        )}
        {dragState?.kind === "project" && (
          <div
            className={`sidebar-drop-end${dragOverID === "__project_end" ? " drag-over" : ""}`}
            onDragOver={event => {
              event.preventDefault();
              event.dataTransfer.dropEffect = "move";
              if (dragOverID !== "__project_end") setDragOverID("__project_end");
            }}
            onDrop={event => {
              if (dragState?.kind !== "project") return;
              event.preventDefault();
              onMoveProject(dragState.id, null);
              endDrag();
            }}
          />
        )}
      </div>
      <footer className="sidebar-footer">
        <button type="button" className="footer-settings" onClick={onOpenSettings}>
          <span className="footer-tile" aria-hidden="true"><SettingsIcon /></span>
          <span>Settings</span>
        </button>
      </footer>
    </aside>
  );
}

export const TopBar = memo(TopBarView);

/// The one Session this window shows.
///
/// The Web client has no split panes, so this header names the Session and
/// holds what acts on it; moving between Sessions is the sidebar's and the
/// phone pill strip's job, and there is no strip of Tabs here pretending the
/// window holds more than one.
function TopBarView({
  session = null,
  workspace = null,
  onNewSession,
  onOpenMenu,
  onOpenSearch,
  onToggleGit,
  gitActive,
  creatingSession = false,
  agentToggle = null,
}) {
  const agentAttention = useTooltipDescription(agentToggle?.attention ? "Agent needs attention" : null);
  const sessionTitle = session ? terminalTabTitle(session, workspace || {}) : "";
  const fallbackTitle = workspace?.branch || workspace?.name || "";

  return (
    <header className="topbar">
      <button type="button" className="menu-button" aria-label="Open navigation" onClick={onOpenMenu}>{MenuIcon}</button>
      <div className="topbar-title" data-tooltip={sessionTitle || fallbackTitle || "Session"}>
        <span className="topbar-session">{sessionTitle || fallbackTitle || "Session"}</span>
      </div>
      <div className="chrome-spacer" />
      {agentToggle && (
        <div className="view-toggle" role="group" aria-label="Session view">
          <button type="button" aria-pressed={!agentToggle.active} onClick={() => agentToggle.onSelect("terminal")}>Terminal</button>
          <button
            type="button"
            aria-pressed={agentToggle.active}
            className={agentToggle.attention ? "has-attention" : undefined}
            {...agentAttention.props}
            onClick={() => agentToggle.onSelect("agent")}
          >
            Agent
          </button>
          {agentAttention.note}
        </div>
      )}
      {/* The panels and "+" sit in one capsule, as on the Desktop. */}
      <div className="chrome-capsule">
        <button type="button" className="chrome-button topbar-search" aria-label="Search projects" onClick={onOpenSearch}>
          <SearchIcon />
        </button>
        <button
          type="button"
          className={`chrome-button${gitActive ? " active" : ""}`}
          aria-label="Toggle Git panel"
          aria-pressed={gitActive}
          onClick={onToggleGit}
        >
          {GitIcon}
        </button>
        <button type="button" className="new-session" aria-label="New session" data-tooltip="New session" disabled={creatingSession} aria-busy={creatingSession || undefined} onClick={onNewSession}>
          <PlusIcon />
        </button>
      </div>
    </header>
  );
}

const backChevron = (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M15 5l-7 7 7 7" />
  </svg>
);

const rowChevron = (
  <svg className="inbox-row-chevron" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M6 3.5 10.5 8 6 12.5" />
  </svg>
);

/// The phone's home: every Session on the Host, by what it asks of you or by
/// Project. Tapping a row pushes that Session's full-screen view over it.
///
/// It stays mounted while a Session is open so coming back keeps the scroll
/// position, and it is inert then so it cannot take focus or taps.
export function MobileInbox({
  open,
  catalog,
  hostName = "",
  connection,
  activeSession = null,
  grouping = "status",
  onGroupingChange,
  onOpenSession,
  onNewSession,
  onOpenSearch,
  onOpenSettings,
  onSessionContextMenu,
  creatingSession = false,
  installHint = null,
}) {
  const acknowledgments = useContext(ActivityAcknowledgmentsContext);
  const sections = useMemo(
    () => inboxSections(catalog, grouping),
    [catalog, grouping],
  );
  const summary = useMemo(() => inboxSummary(catalog), [catalog]);
  const empty = sections.length === 0;

  return (
    <section
      className={`mobile-inbox${open ? " open" : ""}`}
      aria-label="Sessions"
      aria-hidden={open ? undefined : true}
      inert={open ? undefined : true}
    >
      <header className="inbox-bar">
        <span className={connectionClassName("inbox-host", connection)} data-tooltip={connection.message}>
          <span className="inbox-host-tile" aria-hidden="true">
            {monogram(hostName || "Warren")}
            <span className="connection-dot" />
          </span>
          <span className="inbox-host-text">
            <span className="inbox-host-name">{hostName || "Warren"}</span>
            <span className="inbox-host-status">{connection.message}</span>
          </span>
        </span>
        <button type="button" className="inbox-icon-button" aria-label="Search" onClick={onOpenSearch}>
          <SearchIcon />
        </button>
        <button type="button" className="inbox-icon-button" aria-label="Settings" onClick={onOpenSettings}>
          <SettingsIcon />
        </button>
        <button
          type="button"
          className="inbox-new"
          disabled={creatingSession}
          aria-busy={creatingSession || undefined}
          onClick={onNewSession}
        >
          <PlusIcon />
          <span>{creatingSession ? "Starting…" : "New"}</span>
        </button>
      </header>
      <div className="inbox-scroll">
        <div className="inbox-heading">
          <h2>Sessions</h2>
          <p>{summary}</p>
        </div>
        {installHint}
        <div className="inbox-grouping" role="radiogroup" aria-label="Group sessions">
          {[["status", "By status"], ["project", "By project"]].map(([value, label]) => (
            <button
              type="button"
              role="radio"
              aria-checked={grouping === value}
              key={value}
              onClick={() => onGroupingChange?.(value)}
            >
              {label}
            </button>
          ))}
        </div>
        {empty ? (
          <div className="inbox-empty">
            <p className="inbox-empty-title">Nothing running yet</p>
            <p className="inbox-empty-hint">Start a shell or an Agent in one of this Host's Projects.</p>
          </div>
        ) : sections.map(section => (
          <section className={`inbox-section inbox-section-${section.id.split(":")[0]}`} key={section.id} aria-label={section.title}>
            <h3 className="inbox-section-title">
              <span>{section.title}</span>
              <span className="inbox-section-count">{section.rows.length}</span>
            </h3>
            <ul className="inbox-list">
              {section.rows.map(({ session, workspace, project }) => {
                const summaryLine = sessionRowSummary(session);
                const context = grouping === "project"
                  ? (workspace?.branch || workspace?.name || "")
                  : [project?.name, workspace?.branch || workspace?.name].filter(Boolean).join(" · ");
                return (
                  <li key={session.id}>
                    <button
                      type="button"
                      className={`inbox-row${session.id === activeSession ? " current" : ""}`}
                      onClick={() => onOpenSession?.(session.workspace, session.id)}
                      onContextMenu={event => onSessionContextMenu?.(event, session)}
                    >
                      <span className="inbox-row-icon">
                        <SessionPresetIcon kind={sessionProvider(session)} />
                        <ActivityDot session={session} />
                      </span>
                      <span className="inbox-row-text">
                        <span className="inbox-row-title">{terminalTabTitle(session, workspace || {})}</span>
                        {summaryLine.text && <span className={`inbox-row-status ${summaryLine.tone}`}>{summaryLine.text}</span>}
                        {context && <span className="inbox-row-context">{context}</span>}
                      </span>
                      {rowChevron}
                    </button>
                  </li>
                );
              })}
            </ul>
          </section>
        ))}
      </div>
    </section>
  );
}

export function MobileShell({
  workspace,
  projectName,
  tabs,
  activeSession,
  connection,
  agentSession,
  agentViewActive,
  onAttachSession,
  onToggleAgentView,
  onOpenMenu,
  onNewSession,
  onOpenMoreMenu,
  onSessionContextMenu,
  pendingSessionID = null,
  creatingSession = false,
  onBack = null,
}) {
  const handleTabListKeyDown = event => {
    if (!tabs.length) return;
    const focused = tabs.findIndex(session => session.id === event.target?.dataset?.session);
    const current = focused >= 0 ? focused : Math.max(0, tabs.findIndex(session => session.id === activeSession));
    const next = rovingIndex(event.key, current, tabs.length, { orientation: "horizontal" });
    if (next < 0) return;
    event.preventDefault();
    const session = tabs[next];
    if (!session) return;
    if (pendingSessionID || creatingSession) return;
    onAttachSession(session.id);
    document.querySelector(`.mobile-tab[data-session="${session.id}"]`)?.focus();
  };

  return (
    <header className="mobile-shell">
      <div className="mobile-command">
        {onBack
          ? <button type="button" className="menu-button back-button" aria-label="All sessions" onClick={onBack}>{backChevron}</button>
          : <button type="button" className="menu-button" aria-label="Open navigation" onClick={onOpenMenu}>{MenuIcon}</button>}
        {onBack ? (
          // Pushed from the inbox, the header names the Session first and
          // where it lives second, like a detail view's two-line title.
          <div className="mobile-session-title" data-tooltip={connection.message}>
            <span className="mobile-session-name">
              {(() => {
                const current = tabs.find(session => session.id === activeSession);
                return current ? terminalTabTitle(current, workspace || {}) : (workspace?.branch || workspace?.name || "Session");
              })()}
              <span className={connectionClassName("mobile-connection", connection)} aria-label={connection.message}>
                <span className="connection-dot" />
              </span>
            </span>
            <span className="mobile-session-place">
              {[projectName, workspace?.branch || workspace?.name].filter(Boolean).join(" · ")}
            </span>
          </div>
        ) : (
        <div className="mobile-workspace" data-tooltip={connection.message}>
          <div className="mobile-workspace-context" aria-label="Project, workspace and branch">
            {projectName && (
              <>
                <span className="mobile-breadcrumb-item project">{projectName}</span>
                <span className="mobile-breadcrumb-separator" aria-hidden="true">›</span>
              </>
            )}
            <span className="mobile-breadcrumb-item workspace">{workspace?.name || "Workspace"}</span>
            {workspace?.branch && workspace.branch !== workspace.name && (
              <>
                <span className="mobile-breadcrumb-separator" aria-hidden="true">›</span>
                <span className="mobile-breadcrumb-item branch">{workspace.branch}</span>
              </>
            )}
          </div>
          <span className={connectionClassName("mobile-connection", connection)} aria-label={connection.message}>
            <span className="connection-dot" />
          </span>
        </div>
        )}
        {agentSession && (
          <div className="agent-view-toggle" role="group" aria-label="View">
            <button
              type="button"
              className={agentViewActive ? undefined : "active"}
              aria-pressed={!agentViewActive}
              aria-label="Terminal"
              data-tooltip="Terminal"
              onClick={() => onToggleAgentView("terminal")}
            >
              {terminalIcon}
            </button>
            <button
              type="button"
              className={agentViewActive ? "active" : undefined}
              aria-pressed={agentViewActive}
              aria-label="Agent chat"
              data-tooltip="Agent chat"
              onClick={() => onToggleAgentView("agent")}
            >
              {agentChatIcon}
            </button>
          </div>
        )}
        <div className="chrome-spacer" />
        {/* Search and Git live in the overflow menu at phone width: every
            permanent slot here is taken from the breadcrumb, which is the one
            thing that says where you are. */}
        <button type="button" className="chrome-button" aria-label="More actions" onClick={onOpenMoreMenu}>
          {moreIcon}
        </button>
        <button type="button" className="new-session" aria-label="New session" disabled={creatingSession} aria-busy={creatingSession || undefined} onClick={onNewSession}>
          <PlusIcon />
        </button>
      </div>
      <nav className="mobile-tabs" role="tablist" aria-label="Sessions" onKeyDown={handleTabListKeyDown}>
        {tabs.map(session => {
          const active = session.id === activeSession;
          const pending = session.id === pendingSessionID;
          return (
            <button
              type="button"
              role="tab"
              data-session={session.id}
              aria-selected={active}
              tabIndex={active ? 0 : -1}
              className={`mobile-tab${active ? " active" : ""}${pending ? " pending" : ""}`}
              disabled={Boolean(pendingSessionID) || creatingSession}
              aria-busy={pending || undefined}
              key={session.id}
              onClick={() => onAttachSession(session.id)}
              onContextMenu={event => onSessionContextMenu?.(event, session)}
            >
              <ActivityDot session={session} />
              <span className="mobile-tab-title">{terminalTabTitle(session, workspace)}</span>
            </button>
          );
        })}
      </nav>
    </header>
  );
}

export function ContextMenu({ menu, onClose }) {
  const menuRef = useRef(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  const [mobile, setMobile] = useState(() => window.matchMedia("(max-width: 767px)").matches);
  const [placement, setPlacement] = useState(null);
  useFocusRestore(Boolean(menu));
  useFocusTrap(Boolean(menu), menuRef);
  useBodyScrollLock(Boolean(menu) && mobile);

  useEffect(() => {
    const media = window.matchMedia("(max-width: 767px)");
    const onChange = event => setMobile(event.matches);
    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    if (!menu) return undefined;
    const items = () => Array.from(menuRef.current?.querySelectorAll(
      mobile ? 'button:not(:disabled)' : '[role="menuitem"]:not(:disabled)',
    ) || [])
      .filter(item => item.getAttribute("aria-disabled") !== "true");
    const first = items()[0] || menuRef.current?.querySelector("button:not(:disabled)");
    first?.focus();
    const handlePointerDown = event => {
      if (!menuRef.current?.contains(event.target)) onCloseRef.current();
    };
    const handleKeyDown = event => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        onCloseRef.current();
      }
      else if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
        event.preventDefault();
        const list = items();
        if (!list.length) return;
        const current = Math.max(0, list.indexOf(document.activeElement));
        let next = current;
        if (event.key === "ArrowDown") next = (current + 1) % list.length;
        else if (event.key === "ArrowUp") next = (current - 1 + list.length) % list.length;
        else if (event.key === "Home") next = 0;
        else if (event.key === "End") next = list.length - 1;
        list[next]?.focus();
      }
    };
    const handleBlur = () => onCloseRef.current();
    window.addEventListener("pointerdown", handlePointerDown);
    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("blur", handleBlur);
    return () => {
      window.removeEventListener("pointerdown", handlePointerDown);
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("blur", handleBlur);
    };
  }, [Boolean(menu), mobile]);

  // A desktop menu opens at the pointer, so near the right or bottom edge it
  // would overflow the viewport. Measure it before paint and flip or clamp it.
  // The phone sheet is pinned to the bottom edge and needs no placement.
  useLayoutEffect(() => {
    const node = menuRef.current;
    if (!menu || mobile || !node) {
      setPlacement(null);
      return;
    }
    setPlacement(placeMenu(
      { x: menu.x, y: menu.y },
      { width: node.offsetWidth, height: node.offsetHeight },
      { width: window.innerWidth, height: window.innerHeight },
    ));
  }, [menu, mobile]);

  if (!menu) return null;
  return (
    <>
      {mobile && (
        <div
          className="context-menu-scrim"
          aria-hidden="true"
          onPointerDown={event => {
            event.stopPropagation();
            onCloseRef.current();
          }}
        />
      )}
      <div
        ref={menuRef}
        className="context-menu"
        role={mobile ? "dialog" : "menu"}
        aria-modal={mobile ? "true" : undefined}
        aria-label={mobile ? "Actions" : undefined}
        style={placement ? { left: placement.x, top: placement.y } : { left: menu.x, top: menu.y }}
      >
        {menu.items.map((item, index) => (
          <button
            type="button"
            role={mobile ? undefined : "menuitem"}
            className={item.danger ? "danger" : undefined}
            key={index}
            disabled={item.disabled}
            aria-disabled={item.disabled ? "true" : undefined}
            onClick={() => {
              if (item.disabled) return;
              onCloseRef.current();
              item.action();
            }}
          >
            {item.label}
          </button>
        ))}
      </div>
    </>
  );
}

const shareIcon = (
  <svg className="share-glyph" viewBox="0 0 16 16" aria-hidden="true">
    <path d="M8 1.5v8.5M5 4.5l3-3 3 3" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" />
    <path d="M5.5 7H4a1 1 0 0 0-1 1v5.5a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1V8a1 1 0 0 0-1-1h-1.5" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
  </svg>
);

/// The whole screen when this browser holds no working link to a Host.
///
/// It is the first thing a new device sees, so it explains where a link comes
/// from rather than only asking for one. `expired` is the returning case: this
/// browser had a link and the Host no longer accepts it.
export function WelcomeScreen({ onConnect, expired = false, installHint = false, remote = false, initialError = "" }) {
  const [inputValue, setInputValue] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(initialError);

  const handleSubmit = async event => {
    event.preventDefault();
    const trimmed = inputValue.trim();
    if (!trimmed || submitting) return;
    setError("");
    setSubmitting(true);
    try {
      await onConnect?.(trimmed);
    } catch (err) {
      setError(err?.message || "Warren could not connect with that link");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="welcome-screen" role="main" aria-labelledby="welcome-title">
      <div className="welcome-card">
        <img className="welcome-icon" src={webAssetURL("icon.svg")} alt="" width="56" height="56" />
        <h2 id="welcome-title" className="welcome-title">
          {expired ? "This link no longer works" : "Connect to your Warren Host"}
        </h2>
        <p className="welcome-lead">
          {remote
            ? (expired
              ? "The Host stopped accepting this browser. Share a new link from Warren and paste it below."
              : "Warren runs on your own Mac. A share link connects this browser to it, end-to-end encrypted through the relay.")
            : (expired
              ? "The Host stopped accepting this browser's link. Copy a fresh one from Warren (Web › Copy Secure Web URL) and paste it below."
              : "Warren runs on your own Mac or server. Open a Web link from it, and this browser connects straight to that Host.")}
        </p>
        {!expired && (remote ? (
          <ol className="welcome-steps">
            <li>Open Warren on your Mac.</li>
            <li>In <strong>Settings › Access › Serverless relay</strong>, choose <strong>Share</strong>.</li>
            <li>Open the Web link here, or paste it below.</li>
          </ol>
        ) : (
          <ol className="welcome-steps">
            <li>Open Warren on your Mac.</li>
            <li>In the menu bar, choose <strong>Web › Copy Secure Web URL</strong>.</li>
            <li>Open the link here, or paste it below.</li>
          </ol>
        ))}
        <form className="welcome-form" onSubmit={handleSubmit}>
          <input
            type="text"
            className="welcome-input"
            placeholder="Paste a Web link"
            aria-label="Web link"
            value={inputValue}
            onChange={event => {
              setInputValue(event.target.value);
              if (error) setError("");
            }}
            autoFocus={!installHint}
            spellCheck={false}
            autoCapitalize="off"
            autoCorrect="off"
            autoComplete="off"
            enterKeyHint="go"
          />
          <button type="submit" className="welcome-action" disabled={!inputValue.trim() || submitting}>
            {submitting ? "Connecting…" : "Connect"}
          </button>
        </form>
        {error && <p className="welcome-error" role="alert">{error}</p>}
        {installHint && (
          <p className="welcome-install">
            On iPhone, add Warren to your Home Screen first: tap {shareIcon} Share, then <strong>Add to Home Screen</strong>.
            The installed app keeps its own link, so paste it there.
          </p>
        )}
      </div>
    </div>
  );
}

/// A one-line invitation to install, for an iPhone or iPad Safari tab that is
