export function EmptyTerminal({
  activeWorkspace,
  activeSession,
  terminalReadySession,
  tabCount,
  projectCount,
  override,
  onNewSession,
  onReconnect,
}) {
  let content;
  let hidden = false;

  if (override) {
    // The Welcome screen covers the whole window for this case.
    if (override.message === "unauthorized") {
      hidden = true;
      content = null;
    } else {
      content = override.loading ? <Loading message={override.message} /> : <span>{override.message}</span>;
    }
  } else if (activeSession && terminalReadySession === activeSession) {
    hidden = true;
    content = null;
  } else if (activeSession) {
    // Keep the terminal surface quiet while a new subscription is warming.
    // A static status avoids a spinner flash over the cached renderer.
    content = <span className="terminal-switching" role="status" aria-live="polite">Switching session…</span>;
  } else if (activeWorkspace && tabCount) {
    content = (
      <div className="empty-state">
        <div className="empty-title">Select a session</div>
        <p className="empty-hint">Choose a tab above to open its terminal.</p>
      </div>
    );
  } else if (activeWorkspace) {
    content = (
      <div className="empty-state">
        {terminalIcon}
        <div className="empty-title">No sessions here yet</div>
        <p className="empty-hint">Start a shell or an Agent from + in the tab bar.</p>
        <button type="button" className="empty-action" onClick={onNewSession}>New session</button>
      </div>
    );
  } else {
    content = (
      <div className="empty-state">
        {folderIcon}
        <div className="empty-title">{projectCount ? "Select a workspace" : "No projects on this host"}</div>
        <p className="empty-hint">
          {projectCount
            ? "Choose a workspace from the sidebar to open its sessions."
            : "Projects appear here after you connect to a host."}
        </p>
      </div>
    );
  }

  const switching = Boolean(activeSession && terminalReadySession !== activeSession && !override);
  return <div className={`terminal-empty${switching ? " switching" : ""}`} hidden={hidden}>{content}</div>;
}

export const TerminalSearch = memo(function TerminalSearch({
  open,
  resultIndex,
  resultCount,
  focusNonce,
  onQueryChange,
  onNext,
  onPrevious,
  onClose,
}) {
  const inputRef = useRef(null);
  // The field owns its text; App only hears about each change.
  const [query, setQuery] = useState("");

  useEffect(() => {
    if (open) inputRef.current?.focus();
    else setQuery("");
  }, [open, focusNonce]);

  const handleKeyDown = event => {
    if (event.key === "Enter") {
      event.preventDefault();
      if (event.shiftKey) onPrevious();
      else onNext();
    } else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      onClose();
    }
  };

  if (!open) return null;

  const summary = terminalSearchSummary(resultIndex, resultCount, Boolean(query));
  const hasMatches = Boolean(query) && resultCount > 0;
  return (
    <div className="terminal-search" role="search" aria-label="Search terminal">
      <SearchIcon />
      <input
        ref={inputRef}
        value={query}
        onChange={event => {
          setQuery(event.target.value);
          onQueryChange(event.target.value);
        }}
        onKeyDown={handleKeyDown}
        placeholder="Find…"
        aria-label="Find in terminal"
        autoComplete="off"
        spellCheck="false"
      />
      <span className="terminal-search-count">{summary}</span>
      <button type="button" aria-label="Previous match" data-tooltip="Previous match" data-tooltip-shortcut="⇧↵" disabled={!hasMatches} onClick={onPrevious}>
        <ChevronUpIcon />
      </button>
      <button type="button" aria-label="Next match" data-tooltip="Next match" data-tooltip-shortcut="↵" disabled={!hasMatches} onClick={onNext}>
        <ChevronDownIcon />
      </button>
      <button type="button" aria-label="Close search" data-tooltip="Close search" data-tooltip-shortcut="esc" onClick={onClose}>
        <CloseIcon />
      </button>
    </div>
  );
});

export function MobileKeys({ onInput }) {
  const [extended, setExtended] = useState(false);
  // The primary row is always visible; Ctrl chords expand on demand so the
  // keyboard never eats the terminal by default.
  const keyRows = [
    [
      ["escape", "Esc", "\u001b"],
      ["tab", "Tab", "\t"],
      ["home", "Home", "\u001b[H"],
      ["end", "End", "\u001b[F"],
      ["up", "↑", "\u001b[A"],
      ["down", "↓", "\u001b[B"],
      ["left", "←", "\u001b[D"],
      ["right", "→", "\u001b[C"],
    ],
    [
      ["ctrlC", "Ctrl-C", "\u0003"],
      ["ctrlD", "Ctrl-D", "\u0004"],
      ["ctrlA", "Ctrl-A", "\u0001"],
      ["ctrlE", "Ctrl-E", "\u0005"],
      ["ctrlU", "Ctrl-U", "\u0015"],
      ["ctrlK", "Ctrl-K", "\u000b"],
      ["ctrlL", "Ctrl-L", "\u000c"],
    ],
  ];

  return (
    // A tap must not take focus from the terminal: on a phone that collapses
    // the soft keyboard the key was meant to complement. Cancelling the press
    // keeps focus where it is; the click still fires, and panning the row is
    // unaffected.
    <nav
      className="mobile-keys"
      aria-label="Terminal keys"
      onPointerDown={event => event.preventDefault()}
      onMouseDown={event => event.preventDefault()}
    >
      <div className="mobile-key-row">
        {keyRows[0].map(([key, label, sequence]) => (
          <button type="button" className="mobile-key" key={key} onClick={() => onInput(sequence)}>{label}</button>
        ))}
        <button
          type="button"
          className={`mobile-key mobile-key-toggle${extended ? " active" : ""}`}
          aria-pressed={extended}
          aria-label={extended ? "Hide Ctrl keys" : "Show Ctrl keys"}
          onClick={() => setExtended(previous => !previous)}
        >
          Ctrl
        </button>
      </div>
      {extended && (
        <div className="mobile-key-row">
          {keyRows[1].map(([key, label, sequence]) => (
            <button type="button" className="mobile-key" key={key} onClick={() => onInput(sequence)}>{label}</button>
          ))}
        </div>
      )}
    </nav>
  );
}

export function SessionSheet({ open, presets, onChoose, onClose, pendingKind = null, initialKind = "", target = "" }) {
  const firstItemRef = useRef(null);
  const cancelRef = useRef(null);
  const sheetRef = useRef(null);
  const dragStartYRef = useRef(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  const pendingKindRef = useRef(pendingKind);
  pendingKindRef.current = pendingKind;
  const [selectedKind, setSelectedKind] = useState("");
  const [selectedModel, setSelectedModel] = useState("");
  const [selectedReasoning, setSelectedReasoning] = useState("default");
  const [customModel, setCustomModel] = useState("");
  // Chat drives the provider over ACP; Terminal runs its TUI. The last choice
  // is remembered on this device.
  const [sessionInterface, setSessionInterface] = useState(() => {
    try { return localStorage.getItem("warren.session.interface") === "terminal" ? "terminal" : "chat"; } catch { return "chat"; }
  });
  useFocusRestore(open);
  useFocusTrap(open, sheetRef);
  useBodyScrollLock(open);

  useEffect(() => {
    if (!open) return undefined;
    setSelectedKind(presets.some(preset => preset.kind === initialKind) ? initialKind : "");
    setSelectedModel("");
    setSelectedReasoning("default");
    setCustomModel("");
  }, [initialKind, open, presets]);

  useEffect(() => {
    if (!open) return undefined;
    (firstItemRef.current || cancelRef.current)?.focus();
    const handleKeyDown = event => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        if (pendingKindRef.current) return;
        if (selectedKind) setSelectedKind("");
        else onCloseRef.current();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [open, selectedKind]);

  if (!open) return null;
  const selectedPreset = presets.find(preset => preset.kind === selectedKind) || null;
  const isAgentPreset = Boolean(selectedPreset && !["shell", "trae"].includes(selectedPreset.kind));
  const availableModels = selectedPreset ? getAvailableAgentModels(selectedPreset.kind) : [];
  const hasCustomModel = selectedModel && !availableModels.some(model => model.id === selectedModel);
  const offersChat = Boolean(selectedPreset && acpProviders.has(selectedPreset.kind));
  const chat = offersChat && sessionInterface === "chat";
  const chooseInterface = value => {
    setSessionInterface(value);
    try { localStorage.setItem("warren.session.interface", value); } catch { /* optional */ }
  };
  const submitSelection = () => {
    if (!selectedKind || pendingKind) return;
    onChoose(selectedKind, chat ? { handler: "acp" } : {
      model: selectedModel,
      reasoning: selectedReasoning,
    });
  };
  return (
    <div
      className="session-sheet-overlay"
      onClick={event => {
        if (event.target === event.currentTarget && !pendingKindRef.current) onCloseRef.current();
      }}
    >
      <div
        ref={sheetRef}
        className="session-sheet"
        role="dialog"
        aria-modal="true"
        aria-label={target ? `New session in ${target}` : "New session"}
        aria-describedby={target ? "session-sheet-target" : undefined}
        onClick={event => event.stopPropagation()}
      >
        <div
          className="session-sheet-handle"
          role="button"
          tabIndex={0}
          aria-label="Close new session sheet"
          onPointerDown={event => {
            if (event.pointerType === "touch") {
              dragStartYRef.current = event.clientY;
              event.currentTarget.setPointerCapture?.(event.pointerId);
            }
          }}
          onPointerUp={event => {
            const start = dragStartYRef.current;
            dragStartYRef.current = null;
            event.currentTarget.releasePointerCapture?.(event.pointerId);
            if (start !== null && event.clientY - start > 56 && !pendingKindRef.current) onCloseRef.current();
          }}
          onPointerCancel={event => {
            dragStartYRef.current = null;
            event.currentTarget.releasePointerCapture?.(event.pointerId);
          }}
          onKeyDown={event => {
            if (event.key === "Enter" || event.key === " ") {
              event.preventDefault();
              if (!pendingKindRef.current) onCloseRef.current();
            }
          }}
        />
        {selectedPreset ? (
          <>
            <div className="session-sheet-head with-back">
              <div className="session-sheet-title session-sheet-title-with-back">
                <button
                  type="button"
                  className="session-sheet-back"
                  disabled={Boolean(pendingKind)}
                  onClick={() => setSelectedKind("")}
                  aria-label="Choose another session type"
                >
                  ‹
                </button>
                <SessionPresetIcon kind={selectedPreset.kind} />
                <span>{selectedPreset.label}</span>
              </div>
              {target && <div className="session-sheet-context" id="session-sheet-target">in {target}</div>}
            </div>
            {offersChat && (
              <div className="session-sheet-interface" role="radiogroup" aria-label="Interface">
                {[["chat", "Chat", "A conversation view with approvals, no terminal"], ["terminal", "Terminal", "The provider's own terminal UI"]].map(([value, label, hint]) => (
                  <button
                    key={value}
                    type="button"
                    role="radio"
                    aria-checked={sessionInterface === value}
                    className={sessionInterface === value ? "active" : undefined}
                    disabled={Boolean(pendingKind)}
                    onClick={() => chooseInterface(value)}
                  >
                    <span>{label}</span>
                    <small>{hint}</small>
                  </button>
                ))}
              </div>
            )}
            {isAgentPreset && !chat && (
              <div className="session-sheet-options" aria-label="Optional agent settings">
                <label className="session-sheet-field">
                  <span>Model <small>optional</small></span>
                  <select value={selectedModel} onChange={event => setSelectedModel(event.target.value)} disabled={Boolean(pendingKind)}>
                    <option value="">Default session model</option>
                    {hasCustomModel && <option value={selectedModel}>{formatAgentModel(selectedModel) || selectedModel}</option>}
                    {availableModels.map(model => <option value={model.id} key={model.id}>{model.label}</option>)}
                  </select>
                </label>
                <label className="session-sheet-field">
                  <span>Reasoning <small>optional</small></span>
                  <select value={selectedReasoning} onChange={event => setSelectedReasoning(event.target.value)} disabled={Boolean(pendingKind)}>
                    {AGENT_REASONING_OPTIONS.map(option => <option value={option.id} key={option.id}>{option.label}</option>)}
                  </select>
                </label>
                <label className="session-sheet-field">
                  <span>Custom model ID <small>optional</small></span>
                  <div className="session-sheet-custom-model">
                    <input
                      type="text"
                      value={customModel}
                      onChange={event => setCustomModel(event.target.value)}
                      placeholder="provider/model"
                      autoComplete="off"
                      spellCheck="false"
                      disabled={Boolean(pendingKind)}
                    />
                    <button
                      type="button"
                      disabled={!customModel.trim() || Boolean(pendingKind)}
                      onClick={() => {
                        const value = customModel.replace(/[\r\n\u2028\u2029]/g, " ").trim();
                        if (value) {
                          setSelectedModel(value);
                          setCustomModel("");
                        }
                      }}
                    >
                      Set
                    </button>
                  </div>
                </label>
              </div>
            )}
            <button
              ref={firstItemRef}
              type="button"
              className="session-sheet-create"
              disabled={Boolean(pendingKind)}
              aria-busy={pendingKind === selectedKind || undefined}
              onClick={submitSelection}
            >
              {pendingKind === selectedKind ? "Starting…" : "Create session"}
            </button>
          </>
        ) : (
          <>
            <div className="session-sheet-head">
              <div className="session-sheet-title">New session</div>
              {target && <div className="session-sheet-context" id="session-sheet-target">in {target}</div>}
            </div>
            {presets.map((preset, index) => (
              <button
                type="button"
                className="session-sheet-item"
                key={preset.kind}
                ref={index === 0 ? firstItemRef : undefined}
                disabled={Boolean(pendingKind)}
                aria-busy={(!preset.isAgent && pendingKind === preset.kind) || undefined}
                onClick={() => {
                  if (preset.isAgent) {
                    setSelectedKind(preset.kind);
                    setSelectedModel("");
                    setSelectedReasoning("default");
                    setCustomModel("");
                  } else {
                    onChoose(preset.kind);
                  }
                }}
              >
                <SessionPresetIcon kind={preset.kind} />
                <span>{!preset.isAgent && pendingKind === preset.kind ? "Starting…" : preset.label}</span>
              </button>
            ))}
          </>
        )}
        <button
          ref={cancelRef}
          type="button"
          className="session-sheet-cancel"
          disabled={Boolean(pendingKind)}
          onClick={() => {
            if (pendingKind) return;
            if (selectedKind) setSelectedKind("");
            else onCloseRef.current();
          }}
        >
          {selectedKind ? "Back" : "Cancel"}
        </button>
      </div>
    </div>
  );
}

export function WorktreeImportDialog({ dialog, onClose, onToggle, onImport }) {
  const firstItemRef = useRef(null);
  const closeButtonRef = useRef(null);
  const dialogRef = useRef(null);
  const dialogStateRef = useRef(dialog);
  dialogStateRef.current = dialog;
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  useFocusRestore(Boolean(dialog));
  useFocusTrap(Boolean(dialog), dialogRef);

  useEffect(() => {
    if (!dialog) return undefined;
    (firstItemRef.current || closeButtonRef.current)?.focus();
    const handleKeyDown = event => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        const current = dialogStateRef.current;
        const selectedCount = current?.selectedPaths?.length || 0;
        if (current && !current.loading && selectedCount === 0) onCloseRef.current();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [Boolean(dialog)]);

  useBodyScrollLock(Boolean(dialog));

  if (!dialog) return null;
  const candidates = Array.isArray(dialog.candidates) ? dialog.candidates : [];
  const selected = new Set(dialog.selectedPaths || []);
  const availableCount = candidates.filter(candidate => !candidate.imported).length;
  const firstAvailableIndex = candidates.findIndex(candidate => !candidate.imported);

  return (
    <div
      className="worktree-dialog-overlay"
      onClick={() => {
        if (shouldDismissOnBackdrop("sheet", dialog.loading || selected.size > 0)) onClose();
      }}
    >
      <div
        ref={dialogRef}
        className="worktree-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="worktree-dialog-title"
        onClick={event => event.stopPropagation()}
      >
        <div className="worktree-dialog-header">
          <div>
            <h2 id="worktree-dialog-title">Import existing worktrees</h2>
            <p>Choose Git worktrees to register under <strong>{dialog.project.name}</strong>. This is a one-time import: Warren does not create, move, or delete files.</p>
          </div>
          <button ref={closeButtonRef} type="button" className="worktree-dialog-close" aria-label="Close" onClick={onClose}>×</button>
        </div>
        <div className="worktree-dialog-body">
          {dialog.loading ? (
            <Loading message="Reading Git worktrees…" />
          ) : dialog.error ? (
            <div className="worktree-dialog-error" role="alert">{dialog.error}</div>
          ) : !candidates.length ? (
            <div className="worktree-dialog-empty">No external Git worktrees are available to import.</div>
          ) : (
            <div className="worktree-candidate-list" role="listbox" aria-label="Existing Git worktrees" aria-multiselectable="true">
              {candidates.map((candidate, index) => {
                const imported = Boolean(candidate.imported);
                const checked = selected.has(candidate.path);
                return (
                  <button
                    type="button"
                    role="option"
                    aria-selected={checked}
                    aria-disabled={imported}
                    className={`worktree-candidate${checked ? " selected" : ""}${imported ? " imported" : ""}`}
                    key={candidate.path}
                    ref={index === firstAvailableIndex ? firstItemRef : undefined}
                    disabled={imported}
                    onClick={() => onToggle(candidate.path)}
                  >
                    <span className="worktree-candidate-check" aria-hidden="true">{checked ? "☑" : "☐"}</span>
                    <span className="worktree-candidate-copy">
                      <span className="worktree-candidate-title">
                        <span>{candidate.name || candidate.branch || "Worktree"}</span>
                        {candidate.branch && candidate.branch !== candidate.name && <code>{candidate.branch}</code>}
                        {candidate.locked && <span className="worktree-candidate-badge">Locked</span>}
                        {imported && <span className="worktree-candidate-badge">Imported</span>}
                      </span>
                      <span className="worktree-candidate-path">{candidate.path}</span>
                    </span>
                  </button>
                );
              })}
            </div>
          )}
        </div>
        <div className="worktree-dialog-footer">
          <span className="worktree-dialog-summary">
            {dialog.loading ? "" : `${selected.size} selected · ${availableCount} available`}
          </span>
          <div className="worktree-dialog-actions">
            <button type="button" className="worktree-dialog-secondary" onClick={onClose}>Cancel</button>
            <button
              type="button"
              className="worktree-dialog-primary"
              disabled={dialog.loading || Boolean(dialog.error) || selected.size === 0}
              onClick={onImport}
            >
              Import selected
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export function TextInputDialog({
  title,
  message,
  fieldLabel,
  initialValue,
  confirmLabel = "Rename",
  destructive = false,
  onCancel,
  onConfirm,
  pending = false,
  error = "",
}) {
  const inputRef = useRef(null);
  const dialogRef = useRef(null);
  const [text, setText] = useState(initialValue || "");
  const pendingRef = useRef(pending);
  pendingRef.current = pending;
  const onCancelRef = useRef(onCancel);
  onCancelRef.current = onCancel;
  useFocusRestore(true);
  useFocusTrap(true, dialogRef);
  useBodyScrollLock(true);

  useEffect(() => {
    inputRef.current?.focus();
    const handleKeyDown = event => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        if (!pendingRef.current) onCancelRef.current();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, []);

  const submit = () => {
    const trimmed = text.trim();
    if (trimmed) onConfirm(trimmed);
  };

  return (
    <div className="warren-dialog-overlay">
      <div
        ref={dialogRef}
        className="warren-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="warren-dialog-title"
      >
        <h2 id="warren-dialog-title" className="warren-dialog-title">{title}</h2>
        {message && <p className="warren-dialog-message">{message}</p>}
        {error && <p className="warren-dialog-error" role="alert">{error}</p>}
        <label className="warren-dialog-field">
          <span>{fieldLabel}</span>
          <input
            ref={inputRef}
            value={text}
            onChange={event => setText(event.target.value)}
            onKeyDown={event => {
              if (event.key === "Enter") {
                event.preventDefault();
                if (!pending) submit();
              }
            }}
            autoComplete="off"
            spellCheck="false"
          />
        </label>
        <div className="warren-dialog-actions">
          <button type="button" className="warren-dialog-button secondary" disabled={pending} onClick={onCancel}>
            Cancel
          </button>
          <button
            type="button"
            className={`warren-dialog-button ${destructive ? "danger" : "primary"}`}
            disabled={!text.trim() || pending}
            onClick={submit}
          >
            {pending ? "Saving…" : confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

export function ConfirmationDialog({
  title,
  message,
  confirmLabel = "Delete",
  onCancel,
  onConfirm,
  pending = false,
  error = "",
}) {
  const cancelRef = useRef(null);
  const dialogRef = useRef(null);
  const onCancelRef = useRef(onCancel);
  onCancelRef.current = onCancel;
  const pendingRef = useRef(pending);
  pendingRef.current = pending;
  useFocusRestore(true);
  useFocusTrap(true, dialogRef);
  useBodyScrollLock(true);

  useEffect(() => {
    cancelRef.current?.focus();
    const handleKeyDown = event => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        if (!pendingRef.current) onCancelRef.current();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, []);

  return (
    <div className="warren-dialog-overlay">
      <div
        ref={dialogRef}
        className="warren-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="warren-dialog-title"
      >
        <h2 id="warren-dialog-title" className="warren-dialog-title">{title}</h2>
        {message && <p className="warren-dialog-message">{message}</p>}
        {error && <p className="warren-dialog-error" role="alert">{error}</p>}
        <div className="warren-dialog-actions">
          <button
            ref={cancelRef}
            type="button"
            className="warren-dialog-button secondary"
            disabled={pending}
            onClick={onCancel}
          >
            Cancel
          </button>
          <button type="button" className="warren-dialog-button danger" disabled={pending} onClick={onConfirm}>
            {pending ? "Working…" : confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

